CREATE TABLE IF NOT EXISTS "TeamMeeting" ("id" TEXT PRIMARY KEY, "organizationId" TEXT NOT NULL REFERENCES "Organization"("id") ON DELETE CASCADE, "createdById" TEXT NOT NULL REFERENCES "User"("id"), "title" TEXT NOT NULL, "type" TEXT NOT NULL DEFAULT 'Semanal de squad', "startsAt" TIMESTAMP(3) NOT NULL, "endsAt" TIMESTAMP(3) NOT NULL, "location" TEXT NOT NULL DEFAULT '', "agenda" TEXT NOT NULL DEFAULT '', "notes" TEXT NOT NULL DEFAULT '', "status" TEXT NOT NULL DEFAULT 'SCHEDULED', "revision" INTEGER NOT NULL DEFAULT 1, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE IF NOT EXISTS "MeetingParticipant" ("meetingId" TEXT NOT NULL REFERENCES "TeamMeeting"("id") ON DELETE CASCADE, "userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE, PRIMARY KEY("meetingId","userId"));
CREATE TABLE IF NOT EXISTS "MeetingActionItem" ("id" TEXT PRIMARY KEY, "meetingId" TEXT NOT NULL REFERENCES "TeamMeeting"("id") ON DELETE CASCADE, "responsibleId" TEXT NOT NULL REFERENCES "User"("id"), "title" TEXT NOT NULL, "description" TEXT NOT NULL DEFAULT '', "dueAt" TIMESTAMP(3) NOT NULL, "completedAt" TIMESTAMP(3), "revision" INTEGER NOT NULL DEFAULT 1, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE IF NOT EXISTS "MeetingNote" ("id" TEXT PRIMARY KEY, "meetingId" TEXT NOT NULL REFERENCES "TeamMeeting"("id") ON DELETE CASCADE, "authorId" TEXT NOT NULL REFERENCES "User"("id"), "body" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "TeamCalendarEvent" ("id" TEXT PRIMARY KEY, "organizationId" TEXT NOT NULL REFERENCES "Organization"("id") ON DELETE CASCADE, "userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE, "sourceKey" TEXT NOT NULL, "meetingId" TEXT REFERENCES "TeamMeeting"("id") ON DELETE SET NULL, "actionItemId" TEXT REFERENCES "MeetingActionItem"("id") ON DELETE SET NULL, "title" TEXT NOT NULL, "description" TEXT NOT NULL DEFAULT '', "startsAt" TIMESTAMP(3) NOT NULL, "endsAt" TIMESTAMP(3) NOT NULL, "location" TEXT NOT NULL DEFAULT '', "status" TEXT NOT NULL DEFAULT 'ACTIVE', "revision" INTEGER NOT NULL DEFAULT 1, "googleSyncStatus" TEXT NOT NULL DEFAULT 'PENDING', "googleEventId" TEXT, "syncError" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, UNIQUE("userId","sourceKey"));
CREATE TABLE IF NOT EXISTS "GoogleCalendarConnection" ("id" TEXT PRIMARY KEY, "organizationId" TEXT NOT NULL REFERENCES "Organization"("id") ON DELETE CASCADE, "userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE, "encryptedAccessToken" TEXT NOT NULL, "encryptedRefreshToken" TEXT NOT NULL, "expiresAt" TIMESTAMP(3) NOT NULL, "calendarId" TEXT NOT NULL DEFAULT 'primary', "status" TEXT NOT NULL DEFAULT 'CONNECTED', "lastError" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, UNIQUE("organizationId","userId"));
CREATE TABLE IF NOT EXISTS "MeetingDelivery" ("id" TEXT PRIMARY KEY, "organizationId" TEXT NOT NULL REFERENCES "Organization"("id") ON DELETE CASCADE, "userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE, "meetingId" TEXT NOT NULL REFERENCES "TeamMeeting"("id") ON DELETE CASCADE, "actionItemId" TEXT REFERENCES "MeetingActionItem"("id") ON DELETE CASCADE, "dedupeKey" TEXT NOT NULL UNIQUE, "title" TEXT NOT NULL, "body" TEXT NOT NULL, "emailStatus" TEXT NOT NULL DEFAULT 'PENDING', "attempts" INTEGER NOT NULL DEFAULT 0, "leaseUntil" TIMESTAMP(3), "sentAt" TIMESTAMP(3), "lastError" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "MeetingRecording" ("id" TEXT PRIMARY KEY, "meetingId" TEXT NOT NULL REFERENCES "TeamMeeting"("id") ON DELETE CASCADE, "uploadedById" TEXT NOT NULL REFERENCES "User"("id"), "name" TEXT NOT NULL, "mimeType" TEXT NOT NULL, "size" INTEGER NOT NULL, "storagePath" TEXT NOT NULL UNIQUE, "status" TEXT NOT NULL DEFAULT 'UPLOADING', "transcript" TEXT NOT NULL DEFAULT '', "error" TEXT, "consentAt" TIMESTAMP(3) NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE INDEX IF NOT EXISTS "TeamMeeting_organizationId_startsAt_idx" ON "TeamMeeting"("organizationId","startsAt");
CREATE INDEX IF NOT EXISTS "MeetingParticipant_userId_idx" ON "MeetingParticipant"("userId");
CREATE INDEX IF NOT EXISTS "MeetingActionItem_responsibleId_completedAt_dueAt_idx" ON "MeetingActionItem"("responsibleId","completedAt","dueAt");
CREATE INDEX IF NOT EXISTS "MeetingNote_meetingId_createdAt_idx" ON "MeetingNote"("meetingId","createdAt");
CREATE INDEX IF NOT EXISTS "TeamCalendarEvent_organizationId_userId_startsAt_idx" ON "TeamCalendarEvent"("organizationId","userId","startsAt");
CREATE INDEX IF NOT EXISTS "TeamCalendarEvent_googleSyncStatus_updatedAt_idx" ON "TeamCalendarEvent"("googleSyncStatus","updatedAt");
CREATE INDEX IF NOT EXISTS "MeetingDelivery_emailStatus_leaseUntil_idx" ON "MeetingDelivery"("emailStatus","leaseUntil");
CREATE INDEX IF NOT EXISTS "MeetingDelivery_userId_createdAt_idx" ON "MeetingDelivery"("userId","createdAt");
CREATE INDEX IF NOT EXISTS "MeetingRecording_meetingId_createdAt_idx" ON "MeetingRecording"("meetingId","createdAt");
ALTER TABLE "TeamMeeting" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "MeetingParticipant" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "MeetingActionItem" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "MeetingNote" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "TeamCalendarEvent" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "GoogleCalendarConnection" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "MeetingDelivery" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "MeetingRecording" ENABLE ROW LEVEL SECURITY;
